(()=>{const e=document.querySelector(".paper-article");if(!e)return;let t=0,n=0,s=!1;e.querySelectorAll(".post-content > :is(h2,h3)").forEach(o=>{o.tagName==="H2"?(t++,n=0,s=!0):s?n++:t++;const i=o.tagName==="H2"||!s?`${t}`:`${t}.${n}`;o.dataset.section=i;const a=[...e.querySelectorAll(".reading-toc a")].find(e=>decodeURIComponent(e.hash.slice(1))===o.id);if(a){const e=document.createElement("span");e.className="toc-number",e.textContent=i+" ",a.prepend(e)}}),e.querySelectorAll(".citation-back").forEach(t=>{const n=e.querySelector(`.paper-cite[data-key="${CSS.escape(t.dataset.key)}"]`);n&&(t.href="#"+n.id)}),e.querySelectorAll(".reading-figure").forEach((e,t)=>{e.id=`figure-${t+1}`,e.querySelector(".caption-number").textContent=`图 ${t+1} · `})})()